window.SKILL_GROUPS = [{"id": "essentials", "label": "Career essentials", "blurb": "The basics every employer expects from day one."}, {"id": "future", "label": "Future-ready skills", "blurb": "Skills for AI-era, hybrid and fast-changing careers."}, {"id": "growth", "label": "Growth & influence", "blurb": "Stand out, persuade, lead and grow your network."}, {"id": "life", "label": "Life skills", "blurb": "Money and wellbeing habits that support your career."}];
window.SKILL_AREAS = [{"slug": "communication", "group": "essentials", "name": "Communication Skills", "icon": "mail", "color": "#2457f5", "blurb": "Speak clearly, listen well, write emails that get replies and explain things simply.", "id": "ss-communication", "lessons": [{"id": "speaking-clearly-and-concisely", "title": "Speaking Clearly and Concisely at Work", "track": "core", "minutes": 7, "summary": "Structure what you say so that managers, colleagues and clients get your main point in the first few seconds. You will practise leading with the conclusion, cutting filler and checking that your message landed.", "nQuiz": 10, "nScen": 3}, {"id": "active-listening", "title": "Active Listening: Hear What People Actually Mean", "track": "core", "minutes": 7, "summary": "Use attention, clarifying questions and paraphrasing to understand what colleagues and clients actually need. You will learn to listen for concerns behind the words and confirm your understanding before acting.", "nQuiz": 10, "nScen": 3}, {"id": "professional-email-writing", "title": "Writing Professional Emails That Get Replies", "track": "core", "minutes": 8, "summary": "Write work emails with clear subject lines, a direct opening request and an easy-to-scan body. You will learn to rewrite vague emails so that recipients know exactly what to do and by when.", "nQuiz": 10, "nScen": 3}, {"id": "calls-and-video-meetings", "title": "Phone Calls and Video Meetings Etiquette", "track": "core", "minutes": 7, "summary": "Handle work phone calls and video meetings in a way that is respectful of people's time and easy to follow. You will learn how to open and close calls, run your part of a video meeting, and follow up in writing.", "nQuiz": 10, "nScen": 3}, {"id": "workplace-english-and-small-talk", "title": "Workplace English and Small Talk for Your First Job", "track": "fresher", "minutes": 8, "summary": "Use simple, confident workplace English and handle everyday small talk in your first job. You will learn useful phrases for introductions, asking for help, disagreeing politely and starting easy conversations.", "nQuiz": 10, "nScen": 3}, {"id": "explaining-financial-products-to-clients", "title": "Explaining Financial Products Simply to Clients", "track": "professional", "minutes": 9, "summary": "Explain mutual funds, insurance and other financial products in plain language, check that clients have understood, and discuss risks honestly. You will practise turning jargon into everyday explanations without ever promising returns.", "nQuiz": 10, "nScen": 3}]}, {"slug": "interview-career", "group": "essentials", "name": "Interview & Career Skills", "icon": "user", "color": "#7a5af8", "blurb": "Answer interview questions with confidence, shine in group discussions and present yourself well.", "id": "ss-interview-career", "lessons": [{"id": "tell-me-about-yourself", "title": "Answering \"Tell Me About Yourself\"", "track": "core", "minutes": 6, "summary": "Build a 60–90 second answer to \"Tell me about yourself\" that links your background to the role in front of you. You will also learn how to adjust it for campus panels, HR rounds and lateral moves.", "nQuiz": 10, "nScen": 3}, {"id": "common-hr-questions-star-method", "title": "Common HR Questions and the STAR Method", "track": "core", "minutes": 5, "summary": "Recognise what common HR questions are testing and answer behavioural questions with clear, evidence-based STAR stories. You will build a small bank of real examples you can adapt on the spot.", "nQuiz": 10, "nScen": 3}, {"id": "resume-and-linkedin", "title": "A Resume and LinkedIn Profile That Get Shortlisted", "track": "core", "minutes": 5, "summary": "Write a one- or two-page resume and a matching LinkedIn profile that show evidence of results, pass a quick screen and stay accurate. You will rewrite weak duty-style bullet points into outcome-based ones.", "nQuiz": 10, "nScen": 3}, {"id": "salary-discussions", "title": "Discussing Salary and Offers with Confidence", "track": "core", "minutes": 5, "summary": "Understand how CTC, fixed pay, variable pay and in-hand salary differ, and discuss expectations, notice periods and competing offers calmly. You will evaluate an offer on more than just the headline number.", "nQuiz": 10, "nScen": 3}, {"id": "group-discussions", "title": "Group Discussions: Contribute Without Dominating", "track": "fresher", "minutes": 5, "summary": "Prepare for group discussions in bank PO and MBA selection by learning how to open, build on others, bring in quieter members and summarise. You will avoid the common traps of shouting, hijacking and staying silent.", "nQuiz": 10, "nScen": 3}, {"id": "interviewing-for-client-facing-finance-roles", "title": "Interviewing for Client-Facing Finance Roles", "track": "professional", "minutes": 6, "summary": "Show client focus, ethics and suitability thinking in interviews for relationship manager, adviser and distributor roles. You will describe your certifications accurately and handle \"sell me this product\" by asking questions before pitching.", "nQuiz": 10, "nScen": 3}]}, {"slug": "personality", "group": "essentials", "name": "Personality Development", "icon": "sparkle", "color": "#0ea5e9", "blurb": "Build real confidence, body language, professional presence and resilience.", "id": "ss-personality", "lessons": [{"id": "building-confidence", "title": "Building Real Confidence at Work", "track": "core", "minutes": 6, "summary": "Build confidence from evidence and practice rather than pep talks, so you can speak up, admit gaps and take on stretch work without freezing or bluffing.", "nQuiz": 10, "nScen": 3}, {"id": "body-language", "title": "Body Language That Builds Trust", "track": "core", "minutes": 6, "summary": "Use posture, eye contact, gestures and greetings that match your words, so colleagues and clients read you as attentive and trustworthy, in person and on video.", "nQuiz": 10, "nScen": 3}, {"id": "first-impressions-and-grooming", "title": "First Impressions, Grooming and Professional Presence", "track": "core", "minutes": 6, "summary": "Create a reliable first impression through punctuality, preparation and neat, context-appropriate presentation, on any budget and in any attire you choose.", "nQuiz": 10, "nScen": 3}, {"id": "resilience-and-handling-rejection", "title": "Resilience: Handling Rejection and Setbacks", "track": "core", "minutes": 6, "summary": "Use practical habits to respond to rejection and setbacks, recover steadily, learn something useful and keep going without taking each \"no\" personally.", "nQuiz": 10, "nScen": 3}, {"id": "campus-to-corporate", "title": "From Campus to Corporate: Etiquette for Your First Job", "track": "fresher", "minutes": 6, "summary": "Handle the everyday etiquette of your first job, from emails and meetings to deadlines, questions and office relationships, so you are seen as dependable from week one.", "nQuiz": 10, "nScen": 3}, {"id": "building-client-trust-and-credibility", "title": "Building Trust and Credibility with Clients", "track": "professional", "minutes": 6, "summary": "Earn lasting client trust through reliability, plain disclosure of fees and risks, suitable recommendations and consistent follow-through, in line with SEBI and AMFI conduct expectations.", "nQuiz": 10, "nScen": 3}]}, {"slug": "workplace", "group": "essentials", "name": "Workplace Effectiveness", "icon": "briefcase", "color": "#00a87e", "blurb": "Manage time, work in teams, handle conflict and feedback, and present your ideas.", "id": "ss-workplace", "lessons": [{"id": "time-management-and-prioritisation", "title": "Time Management and Prioritisation", "track": "core", "minutes": 7, "summary": "Sort your work by urgency and importance, plan realistic weeks and days, and protect time for focused work. You will also learn how to handle new requests and flag delays without losing trust.", "nQuiz": 10, "nScen": 3}, {"id": "teamwork-and-collaboration", "title": "Teamwork and Collaboration", "track": "core", "minutes": 7, "summary": "Set clear roles, become someone teammates can rely on, and collaborate across seniority, languages and locations. You will also practise disagreeing constructively and committing once a decision is made.", "nQuiz": 10, "nScen": 3}, {"id": "emotional-intelligence-and-conflict", "title": "Emotional Intelligence and Handling Conflict", "track": "core", "minutes": 8, "summary": "Recognise and manage your own reactions, read what others may be feeling, and work through disagreements with a clear step-by-step approach. You will also know when a conflict needs formal channels instead.", "nQuiz": 10, "nScen": 3}, {"id": "presentations-and-public-speaking", "title": "Presentations and Public Speaking", "track": "core", "minutes": 7, "summary": "Build a presentation around one clear message, design slides that support your listeners, and deliver with confidence. You will also learn to handle tough questions and the unexpected.", "nQuiz": 10, "nScen": 3}, {"id": "feedback-and-your-first-manager", "title": "Taking Feedback and Working with Your First Manager", "track": "fresher", "minutes": 7, "summary": "Receive feedback without getting defensive, turn vague comments into specific actions using the SBI model, and build a strong working relationship with your first manager.", "nQuiz": 10, "nScen": 3}, {"id": "handling-client-objections", "title": "Handling Client Objections and Difficult Conversations", "track": "professional", "minutes": 9, "summary": "Handle client concerns about market falls, fees and unsuitable requests with a calm, structured approach. You will learn to stay transparent, avoid promising returns and say no when a request isn't right for the client.", "nQuiz": 10, "nScen": 3}]}, {"slug": "ai-at-work", "group": "future", "name": "Working with AI", "icon": "sparkle", "color": "#7a5af8", "featured": true, "blurb": "Use AI tools to work faster — write good prompts, check the output and keep data safe.", "id": "ss-ai-at-work", "lessons": [{"id": "writing-good-prompts", "title": "Writing Prompts That Get Useful Answers", "track": "core", "minutes": 7, "summary": "Write prompts for AI chat tools that give the task, the context and the format you need. You will learn to turn a one-line request into a clear brief and to improve answers through follow-up instead of starting over.", "nQuiz": 10, "nScen": 3}, {"id": "checking-ai-output", "title": "Checking AI Output Before You Use It", "track": "core", "minutes": 8, "summary": "Spot made-up facts, wrong figures and one-sided answers in AI output before they reach your manager or client. You will learn a practical way to verify claims and to match the depth of checking to the stakes.", "nQuiz": 10, "nScen": 3}, {"id": "using-ai-safely", "title": "Using AI Safely: Privacy, Confidentiality and Ethics", "track": "core", "minutes": 8, "summary": "Decide what you can and cannot share with AI tools and follow your organisation's rules. You will learn to remove personal and confidential data from prompts, and to be honest about when you have used AI.", "nQuiz": 10, "nScen": 3}, {"id": "ai-for-everyday-work", "title": "Using AI for Emails, Research and Summaries", "track": "core", "minutes": 8, "summary": "Use AI chat tools to draft emails, summarise long documents and start research faster, while keeping your own judgement in charge. You will learn practical prompts for each task and when doing it yourself is quicker.", "nQuiz": 10, "nScen": 3}, {"id": "ai-in-your-job-search", "title": "Using AI Honestly in Your Job Search", "track": "fresher", "minutes": 8, "summary": "Use AI to tailor your resume, draft cover letters and practise interviews without inventing anything about yourself. You will learn where the line is during online tests and interviews so that a shortcut never costs you an offer.", "nQuiz": 10, "nScen": 3}, {"id": "ai-for-finance-professionals", "title": "AI for Finance Professionals: Client Data and Compliance", "track": "professional", "minutes": 9, "summary": "Use AI to save time on drafting and preparation while keeping client data private and meeting conduct expectations. You will learn why suitability and advice stay your responsibility, how to check AI-generated figures and what records to keep.", "nQuiz": 10, "nScen": 3}]}, {"slug": "critical-thinking", "group": "future", "name": "Critical Thinking & Problem Solving", "icon": "bulb", "color": "#f79009", "blurb": "Break down problems, ask better questions, spot misinformation and decide with confidence.", "id": "ss-critical-thinking", "lessons": [{"id": "breaking-down-problems", "title": "Breaking Down Big Problems", "track": "core", "minutes": 7, "summary": "Turn a vague, overwhelming problem into a clear question and smaller parts you can actually work on. You will learn to define the problem, split it with an issue tree, find the root cause and choose where to start.", "nQuiz": 10, "nScen": 3}, {"id": "asking-better-questions", "title": "Asking Better Questions", "track": "core", "minutes": 6, "summary": "Ask clear, specific questions that get useful answers from managers, clients and teammates. You will learn when to use open and closed questions, how to clarify a task before starting and how to ask for help well.", "nQuiz": 10, "nScen": 3}, {"id": "spotting-misinformation", "title": "Spotting Fake News, Bad Data and Misleading Charts", "track": "core", "minutes": 7, "summary": "Check forwards, statistics and charts before you believe or share them. You will learn quick verification habits and how to spot cherry-picked numbers and misleading graphs.", "nQuiz": 10, "nScen": 3}, {"id": "deciding-with-incomplete-information", "title": "Making Decisions with Incomplete Information", "track": "core", "minutes": 7, "summary": "Make sound decisions when you cannot know everything, by sorting what you know, matching effort to the stakes and setting a deadline to decide. You will also learn to judge decisions by their reasoning, not only their outcome.", "nQuiz": 10, "nScen": 3}, {"id": "case-and-puzzle-questions", "title": "Solving Case and Puzzle Questions in Interviews", "track": "fresher", "minutes": 7, "summary": "Approach guesstimates, business cases and puzzles in interviews with a clear structure and calm, out-loud reasoning. You will learn to clarify the question, break it down, calculate simply and sanity-check your answer.", "nQuiz": 10, "nScen": 3}, {"id": "questioning-financial-claims", "title": "Questioning Financial Claims and Market \"Tips\"", "track": "professional", "minutes": 7, "summary": "Evaluate return claims, track records and market tips with healthy scepticism, and help clients do the same. You will learn to spot red flags, survivorship bias and misuse of past performance, and to check whether an adviser is registered.", "nQuiz": 10, "nScen": 3}]}, {"slug": "adaptability", "group": "future", "name": "Adaptability & Learning How to Learn", "icon": "refresh", "color": "#6172f3", "blurb": "Learn new skills faster, handle change at work and plan a career switch with confidence.", "id": "ss-adaptability", "lessons": [{"id": "learning-anything-faster", "title": "Learning Anything Faster", "track": "core", "minutes": 8, "summary": "Use three well-researched techniques — testing yourself, spacing your practice and explaining to others — to learn new skills in less time. You will be able to replace rereading and cramming with a simple weekly learning plan.", "nQuiz": 10, "nScen": 3}, {"id": "growth-mindset-in-practice", "title": "A Growth Mindset in Practice", "track": "core", "minutes": 7, "summary": "Turn the idea that abilities can grow into everyday habits: rewriting self-limiting thoughts, using feedback as data and reviewing mistakes calmly. You will be able to pick stretch goals and track real progress.", "nQuiz": 10, "nScen": 3}, {"id": "handling-change-at-work", "title": "Handling Change at Work", "track": "core", "minutes": 8, "summary": "Respond to reorganisations, new managers and new tools with clear questions, practical learning steps and constructive feedback. You will be able to stay productive and credible while things around you shift.", "nQuiz": 10, "nScen": 3}, {"id": "switching-careers", "title": "Planning a Career Switch", "track": "core", "minutes": 9, "summary": "Plan a career change step by step: clarify your reasons, research the new field, map transferable skills, test with small experiments and prepare financially. You will be able to explain your switch convincingly in interviews.", "nQuiz": 10, "nScen": 3}, {"id": "from-exam-prep-to-job-skills", "title": "From Exam Prep to Job Skills: Learning Beyond the Syllabus", "track": "fresher", "minutes": 8, "summary": "Turn the discipline you built preparing for competitive exams into strong workplace learning habits. You will be able to learn without a syllabus, handle open-ended tasks and talk about your preparation years with confidence.", "nQuiz": 10, "nScen": 3}, {"id": "keeping-up-with-rule-changes", "title": "Keeping Up with Rule Changes as a Finance Professional", "track": "professional", "minutes": 9, "summary": "Build a simple routine to track regulatory changes from reliable sources, keep your certifications valid and explain changes to clients accurately. You will be able to turn a new circular into clear actions for your practice.", "nQuiz": 10, "nScen": 3}]}, {"slug": "productivity-focus", "group": "future", "name": "Productivity & Focus", "icon": "clock", "color": "#00a87e", "blurb": "Beat phone distraction, protect deep-work time and get the important things done.", "id": "ss-productivity-focus", "lessons": [{"id": "beating-digital-distraction", "title": "Beating Digital Distraction", "track": "core", "minutes": 7, "summary": "Cut unnecessary notifications, place your phone where it cannot pull you away, and break the automatic scroll habit. You will leave with a notification plan and a simple routine for checking your phone on your terms.", "nQuiz": 10, "nScen": 3}, {"id": "deep-work-blocks", "title": "Deep-Work Blocks for Focused Results", "track": "core", "minutes": 7, "summary": "Plan and protect blocks of uninterrupted time for your most demanding work. You will learn to define a clear finish line, guard the block from interruptions and end it with a next step ready.", "nQuiz": 10, "nScen": 3}, {"id": "planning-your-week", "title": "Planning Your Week in 20 Minutes", "track": "core", "minutes": 7, "summary": "Run a simple 20-minute weekly planning routine: review last week, capture everything, choose three outcomes and place them in your calendar. You will also learn a five-minute daily check to keep the plan realistic.", "nQuiz": 10, "nScen": 3}, {"id": "busy-vs-productive", "title": "Busy vs Productive: Doing What Matters", "track": "core", "minutes": 7, "summary": "Tell the difference between looking busy and moving important work forward. You will learn to spot busy-work, judge your day by results, renegotiate low-value requests and stop over-polishing small tasks.", "nQuiz": 10, "nScen": 3}, {"id": "balancing-work-and-upskilling", "title": "Balancing a Job, Exams and Upskilling", "track": "fresher", "minutes": 8, "summary": "Build a realistic weekly routine that fits exam preparation or a course around a full-time job. You will learn to map your real free time, choose one main goal per season, use fixed study slots and handle busy work periods without guilt.", "nQuiz": 10, "nScen": 3}, {"id": "productive-client-days", "title": "Running a Productive Day of Client Meetings and Paperwork", "track": "professional", "minutes": 8, "summary": "Plan a day of client meetings so that preparation, travel, notes and paperwork fit together. You will learn to cluster meetings, prepare in ten minutes, record notes straight after each meeting and close the day with nothing left hanging.", "nQuiz": 10, "nScen": 3}]}, {"slug": "remote-hybrid", "group": "future", "name": "Remote & Hybrid Work", "icon": "phone", "color": "#0ea5e9", "blurb": "Communicate across time and distance, stay visible and stay disciplined when working remotely.", "id": "ss-remote-hybrid", "lessons": [{"id": "async-communication", "title": "Async Communication That Moves Work Forward", "track": "core", "minutes": 7, "summary": "Write messages and updates that a colleague can act on hours later without a follow-up call. You will learn to give full context, set clear timelines and know when to switch to a live conversation.", "nQuiz": 10, "nScen": 3}, {"id": "chat-etiquette", "title": "Teams, Slack and WhatsApp Etiquette for Work", "track": "core", "minutes": 7, "summary": "Choose the right chat channel for each kind of message and write chats that respect colleagues' time and boundaries. You will learn practical habits for threads, mentions, voice notes and work WhatsApp groups.", "nQuiz": 10, "nScen": 3}, {"id": "being-visible-remotely", "title": "Being Visible When You Work Remotely", "track": "core", "minutes": 7, "summary": "Make your work and contribution visible to your manager and team without bragging or working longer hours. You will learn to write short weekly updates, contribute in online meetings and build relationships deliberately.", "nQuiz": 10, "nScen": 3}, {"id": "self-discipline-at-home", "title": "Self-Discipline When Working from Home", "track": "core", "minutes": 8, "summary": "Set up a workable routine, space and backup plan for working from an Indian home, with family, shared rooms and power cuts in the picture. You will learn to protect focus time and end the workday on time.", "nQuiz": 10, "nScen": 3}, {"id": "starting-a-job-remotely", "title": "Starting Your First Job Remotely", "track": "fresher", "minutes": 8, "summary": "Prepare for a remote or hybrid first job and settle in confidently during the first month. You will learn how to get set up, ask good questions, connect with teammates you haven't met and ask for early feedback.", "nQuiz": 10, "nScen": 3}, {"id": "serving-clients-remotely", "title": "Serving Clients over Video and Phone", "track": "professional", "minutes": 9, "summary": "Run client conversations over video and phone that are secure, compliant and easy for the client to follow. You will learn to confirm identity and consent, share screens safely, explain products suitably and send clear follow-up summaries.", "nQuiz": 10, "nScen": 3}]}, {"slug": "personal-branding", "group": "growth", "name": "Personal Branding & Networking", "icon": "user", "color": "#2457f5", "featured": true, "blurb": "Get found on LinkedIn, post with confidence and build a network that opens doors.", "id": "ss-personal-branding", "lessons": [{"id": "linkedin-profile-that-gets-found", "title": "A LinkedIn Profile That Gets Found", "track": "core", "minutes": 8, "summary": "Write a LinkedIn headline, About section and skills list that use the words recruiters and peers actually search for. You will turn a generic profile into a specific, honest one that people can find and trust.", "nQuiz": 10, "nScen": 3}, {"id": "posting-without-the-cringe", "title": "Posting on LinkedIn Without the Cringe", "track": "core", "minutes": 8, "summary": "Write short, useful LinkedIn posts and comments that sound like you, not like a template. You will learn simple post formats, a four-line structure and the common habits that make posts feel fake.", "nQuiz": 10, "nScen": 3}, {"id": "networking-at-events-and-online", "title": "Networking at Events and Online", "track": "core", "minutes": 8, "summary": "Start conversations at events, send connection requests people accept, and follow up so that a single meeting becomes a lasting professional relationship. You will practise openers, graceful exits and follow-up messages.", "nQuiz": 10, "nScen": 3}, {"id": "asking-for-referrals", "title": "Asking for Referrals and Introductions", "track": "core", "minutes": 7, "summary": "Ask for job referrals and introductions in a way that is specific, easy to say yes to and easy to decline. You will write a forwardable request and learn how to follow up and say thank you.", "nQuiz": 10, "nScen": 3}, {"id": "personal-brand-with-no-experience", "title": "Building a Personal Brand with No Experience", "track": "fresher", "minutes": 8, "summary": "Build a credible professional reputation as a student or fresher by choosing a focus, creating small pieces of proof and learning in public. You will plan a simple 30-day routine you can actually keep.", "nQuiz": 10, "nScen": 3}, {"id": "building-trust-online-finance", "title": "Building Trust Online as a Finance Professional", "track": "professional", "minutes": 9, "summary": "Build a credible online presence as a distributor, adviser or bank RM by describing your role accurately, sharing education instead of promises and protecting client data. You will rewrite risky posts into compliant, trustworthy ones.", "nQuiz": 10, "nScen": 3}]}, {"slug": "negotiation", "group": "growth", "name": "Negotiation & Persuasion", "icon": "target", "color": "#eb5b3c", "blurb": "Prepare your ask, find win–win outcomes and persuade people without pressure.", "id": "ss-negotiation", "lessons": [{"id": "preparing-to-negotiate", "title": "Preparing to Negotiate", "track": "core", "minutes": 7, "summary": "Prepare for any negotiation by fixing a clear goal, a walk-away point and a Plan B. You will also learn to map what the other side really needs before you say a word.", "nQuiz": 10, "nScen": 3}, {"id": "creating-win-win-offers", "title": "Creating Win–Win Offers", "track": "core", "minutes": 7, "summary": "Build offers that give both sides more of what they value, by bringing several issues to the table and trading instead of conceding. You will learn to present options and close with a clear written agreement.", "nQuiz": 10, "nScen": 3}, {"id": "handling-no-and-counter-offers", "title": "Handling \"No\" and Tough Counter-Offers", "track": "core", "minutes": 7, "summary": "Respond calmly when someone says no or makes a tough counter-offer. You will learn to find the reason behind a refusal, reply with criteria instead of emotion, and walk away politely when needed.", "nQuiz": 10, "nScen": 3}, {"id": "persuading-without-pressure", "title": "Persuading Without Pressure", "track": "core", "minutes": 7, "summary": "Persuade colleagues, friends and clients by linking your idea to their goals, backing it with evidence and respecting their right to say no. You will learn to spot and avoid manipulative tactics.", "nQuiz": 10, "nScen": 3}, {"id": "negotiating-deadlines-and-workload", "title": "Negotiating Deadlines and Workload in Your First Job", "track": "fresher", "minutes": 7, "summary": "Handle new tasks, tight deadlines and overload in your first job without saying a blunt no or quietly burning out. You will learn to clarify requests, ask your manager to prioritise and propose realistic options early.", "nQuiz": 10, "nScen": 3}, {"id": "negotiating-terms-with-clients", "title": "Negotiating Fees and Terms with Clients Ethically", "track": "professional", "minutes": 8, "summary": "Discuss fees, commissions and service terms with clients openly, negotiate only what you are allowed to change, and never let a sale override suitability. You will learn phrases for fee conversations and how to record what you agree.", "nQuiz": 10, "nScen": 3}]}, {"slug": "storytelling", "group": "growth", "name": "Storytelling & Pitching", "icon": "book", "color": "#7a5af8", "blurb": "Turn ideas into stories people remember — in pitches, presentations and posts.", "id": "ss-storytelling", "lessons": [{"id": "the-three-part-story", "title": "The Three-Part Story", "track": "core", "minutes": 7, "summary": "Shape any work experience into a short situation–challenge–result story. You will learn to cut background, make the problem concrete and end with a clear outcome and lesson.", "nQuiz": 10, "nScen": 3}, {"id": "pitching-in-60-seconds", "title": "Pitching an Idea in 60 Seconds", "track": "core", "minutes": 7, "summary": "Pitch an idea to a manager, team or panel in about a minute. You will learn to lead with the problem, state your idea in one sentence, give one proof point and end with a clear ask.", "nQuiz": 10, "nScen": 3}, {"id": "stories-with-data", "title": "Telling Stories with Data", "track": "core", "minutes": 8, "summary": "Turn a page of numbers into a clear message people remember. You will learn to choose one key number, add context, use simple comparisons and check that every figure is correct.", "nQuiz": 10, "nScen": 3}, {"id": "storytelling-on-social-media", "title": "Storytelling on Social Media", "track": "core", "minutes": 7, "summary": "Write short posts on LinkedIn and similar platforms that people read to the end. You will learn to open with a strong first line, tell one small story honestly and protect other people's privacy.", "nQuiz": 10, "nScen": 3}, {"id": "stories-in-interviews", "title": "Using Stories to Stand Out in Interviews and GDs", "track": "fresher", "minutes": 8, "summary": "Answer interview questions with short, specific stories instead of claims. You will learn to build a small story bank, fit stories to common questions and use examples briefly in group discussions.", "nQuiz": 10, "nScen": 3}, {"id": "stories-that-help-clients-decide", "title": "Stories That Help Clients Understand Investing", "track": "professional", "minutes": 9, "summary": "Use clearly labelled illustrative stories to explain goals, time horizons and risk to clients. You will learn to make concepts relatable without cherry-picking returns, implying guarantees or skipping suitability and cost disclosure.", "nQuiz": 10, "nScen": 3}]}, {"slug": "first-time-manager", "group": "growth", "name": "First-Time Manager", "icon": "briefcase", "color": "#2e90fa", "blurb": "Make the jump from peer to boss — delegate, give feedback and lead your first team.", "id": "ss-first-time-manager", "lessons": [{"id": "from-peer-to-boss", "title": "From Peer to Boss", "track": "core", "minutes": 7, "summary": "Handle the first weeks after being promoted over your former colleagues. You will learn how to reset relationships, set fair boundaries and earn credibility without trying to prove yourself overnight.", "nQuiz": 10, "nScen": 3}, {"id": "delegating-well", "title": "Delegating Well", "track": "core", "minutes": 7, "summary": "Decide what to hand over, brief people so they can deliver, and check progress without micromanaging. You will learn a simple briefing structure and how to match the level of freedom to the person.", "nQuiz": 10, "nScen": 3}, {"id": "giving-feedback-as-a-manager", "title": "Giving Feedback as a Manager", "track": "core", "minutes": 8, "summary": "Give specific praise, useful corrective feedback and handle difficult conversations calmly. You will learn a simple situation-behaviour-impact structure and phrases you can use the same day.", "nQuiz": 10, "nScen": 3}, {"id": "running-one-on-ones", "title": "Running Useful One-on-Ones", "track": "core", "minutes": 7, "summary": "Run regular one-on-ones that your team finds useful rather than a status check. You will learn how to set a rhythm, use good questions and follow through on what you hear.", "nQuiz": 10, "nScen": 3}, {"id": "leading-without-the-title", "title": "Leading Without the Title", "track": "fresher", "minutes": 7, "summary": "Show leadership in your first job before you manage anyone. You will learn how to own your work, take sensible initiative, influence peers and make your interest in leading visible.", "nQuiz": 10, "nScen": 3}, {"id": "leading-a-sales-or-advisory-team", "title": "Leading a Sales or Advisory Team Ethically", "track": "professional", "minutes": 8, "summary": "Lead relationship managers or advisers so that targets are met through suitable advice, not mis-selling. You will learn how to set balanced goals, coach client conversations, handle complaints and escalate compliance concerns.", "nQuiz": 10, "nScen": 3}]}, {"slug": "customer-sales", "group": "growth", "name": "Customer & Sales Conversations", "icon": "star", "color": "#f79009", "blurb": "Build rapport, understand needs before pitching and follow up without being pushy.", "id": "ss-customer-sales", "lessons": [{"id": "building-rapport", "title": "Building Rapport Quickly", "track": "core", "minutes": 7, "summary": "Open customer conversations in a way that makes people comfortable talking to you. You will learn to prepare, greet well, listen visibly and find genuine common ground without sounding scripted.", "nQuiz": 10, "nScen": 3}, {"id": "ask-before-you-pitch", "title": "Needs-Based Conversations: Ask Before You Pitch", "track": "core", "minutes": 8, "summary": "Use discovery questions to understand what a customer actually needs before recommending anything. You will learn to ask open questions, dig one level deeper, confirm needs in a summary and link your recommendation to what you heard.", "nQuiz": 10, "nScen": 3}, {"id": "follow-ups-that-arent-pushy", "title": "Follow-Ups That Aren't Pushy", "track": "core", "minutes": 7, "summary": "Follow up with customers in a way that is helpful rather than annoying. You will learn to agree the next step before a conversation ends, add value in each message, choose the right channel and timing, and close the loop gracefully.", "nQuiz": 10, "nScen": 3}, {"id": "getting-referrals-from-customers", "title": "Getting Referrals from Happy Customers", "track": "core", "minutes": 7, "summary": "Ask satisfied customers for referrals at the right moment and in a way that feels natural. You will learn to earn the referral first, make a specific ask, respect privacy and consent, and thank both the customer and the person referred.", "nQuiz": 10, "nScen": 3}, {"id": "handling-customer-queries", "title": "Handling Customer Queries and Complaints in Your First Job", "track": "fresher", "minutes": 8, "summary": "Handle customer questions and complaints calmly in a bank branch, call centre or retail job. You will learn a simple step-by-step approach, phrases that calm people down, how to give honest timelines and when and how to escalate.", "nQuiz": 10, "nScen": 3}, {"id": "ethical-selling-and-suitability", "title": "Ethical Selling: Suitability, Disclosure and Saying No", "track": "professional", "minutes": 9, "summary": "Run a suitability-first sales process as a distributor, adviser or relationship manager. You will learn to assess a client's situation and risk, disclose risks, costs and your earnings clearly, document the basis of your recommendation and decline sales that do not fit.", "nQuiz": 10, "nScen": 3}]}, {"slug": "money-skills", "group": "life", "name": "Money Skills for Young Earners", "icon": "pie", "color": "#00a87e", "featured": true, "blurb": "Plan your salary, budget without stress, avoid debt traps and understand investing basics.", "note": "Educational content only — not investment, tax or financial advice. Consider your own situation or consult a SEBI-registered investment adviser before making financial decisions.", "id": "ss-money-skills", "lessons": [{"id": "your-first-salary-plan", "title": "Your First Salary: A Simple Plan", "track": "core", "minutes": 7, "summary": "Understand what actually reaches your bank account each month and set up a simple plan for your first salary. You will learn to build an emergency fund first and automate saving so it happens without willpower.", "nQuiz": 10, "nScen": 3}, {"id": "budgeting-that-works", "title": "Budgeting That Actually Works", "track": "core", "minutes": 7, "summary": "Set up a simple budget you can actually stick to, using a split like 50/30/20 as a starting point. You will learn to spot where small UPI payments leak money and plan for yearly expenses before they surprise you.", "nQuiz": 10, "nScen": 3}, {"id": "credit-cards-loans-and-bnpl", "title": "Credit Cards, Loans and Buy-Now-Pay-Later Traps", "track": "core", "minutes": 8, "summary": "Use credit cards, EMIs and buy-now-pay-later without falling into expensive debt. You will learn why paying only the minimum due is costly, what affects your credit score and how to check the true cost of an EMI.", "nQuiz": 10, "nScen": 3}, {"id": "investing-basics", "title": "Investing Basics: Compounding, Risk and Time", "track": "core", "minutes": 8, "summary": "Understand the core ideas behind investing: compounding, inflation, risk versus return, diversification and time horizon. You will learn to judge claims critically and see why starting early and investing regularly matter.", "nQuiz": 10, "nScen": 3}, {"id": "money-scams-targeting-young-people", "title": "Money Scams Targeting Students and Freshers", "track": "fresher", "minutes": 8, "summary": "Recognise the money scams most often aimed at students and freshers, from fake job fees to UPI collect-request fraud. You will learn the warning signs, what never to share, and exactly what to do if you are targeted.", "nQuiz": 10, "nScen": 3}, {"id": "helping-clients-build-money-habits", "title": "Helping Clients Build Better Money Habits", "track": "professional", "minutes": 8, "summary": "Hold useful goal and habit conversations with clients while staying within your role and regulatory responsibilities. You will learn to educate without pushing products, keep conversations suitable and honest, and know when to refer a client to a registered adviser.", "nQuiz": 10, "nScen": 3}]}, {"slug": "stress-burnout", "group": "life", "name": "Stress, Burnout & Work–Life Balance", "icon": "shield", "color": "#0ea5e9", "featured": true, "blurb": "Spot burnout early, set boundaries politely and build routines that help you recover.", "note": "Practical everyday advice, not medical advice. If stress, low mood or anxiety lasts for weeks or affects daily life, please talk to a doctor or qualified counsellor.", "id": "ss-stress-burnout", "lessons": [{"id": "spotting-burnout-early", "title": "Spotting Burnout Early", "track": "core", "minutes": 7, "summary": "Recognise the early signs of burnout before they pile up, and take sensible first steps. You will learn a simple weekly self-check and what to do when the warning lights come on.", "nQuiz": 10, "nScen": 3}, {"id": "setting-boundaries-politely", "title": "Setting Boundaries at Work Politely", "track": "core", "minutes": 7, "summary": "Set clear, polite limits around late-night messages, weekend work and workload without sounding difficult. You will learn ready-to-use phrases and how to agree boundaries with your manager.", "nQuiz": 10, "nScen": 3}, {"id": "saying-no-without-guilt", "title": "Saying No Without Guilt", "track": "core", "minutes": 7, "summary": "Decline requests clearly and kindly, and handle the guilt that often follows. You will learn a simple three-part no, how to offer real alternatives and how to respond calmly to pushback.", "nQuiz": 10, "nScen": 3}, {"id": "daily-recovery-routines", "title": "Daily Recovery: Sleep, Breaks and Switching Off", "track": "core", "minutes": 7, "summary": "Build simple daily habits that help you recover from work: steadier sleep, real breaks and a clear end to the workday. You will put together a small routine that fits your schedule.", "nQuiz": 10, "nScen": 3}, {"id": "first-job-pressure-and-imposter-feelings", "title": "Handling First-Job Pressure and Imposter Feelings", "track": "fresher", "minutes": 7, "summary": "Understand why your first job can feel overwhelming and what imposter feelings are. You will learn practical ways to ask for help, track your progress and talk to yourself more fairly, and when to seek support.", "nQuiz": 10, "nScen": 3}, {"id": "handling-target-pressure", "title": "Handling Target Pressure in Finance and Sales Roles", "track": "professional", "minutes": 8, "summary": "Cope with sales and business targets in a healthy, ethical way. You will learn to break targets into daily actions, keep suitability ahead of numbers and have a constructive conversation with your manager.", "nQuiz": 10, "nScen": 3}]}];
